function injectTop(){document.getElementById('v1216bTopMoves')?.remove();const rows=topRows();const host=document.querySelector('.v106-top-hero')||document.querySelector('.v106-perf')||document.querySelector('[class*="top-hero"]');if(!host)return;const panel=document.createElement('section');panel.id='v1216bTopMoves';panel.className='v1216b-top-panel';panel.innerHTML=`<div class="v1216b-top-head"><div><span>REACCIONES · TOP</span><h2>Quién está reconociendo a quién</h2><p>Reacciones asociadas a Moves RigGO reales del histórico.</p></div></div>${rows.length?`<div class="v1216b-top-list">${rows.map((x,i)=>`<div class="v1216b-top-move" data-v1216b-topmove="${x.id}"><div class="v1216b-top-move-main"><span class="pos">#${i+1}</span><div><b>${esc(x.rig)} · ${esc(x.operator||'')}</b><small>${esc(x.origin||'')} → ${esc(x.destination||'')} · Gross ${rounds(x.gross,1)} d · Net ${rounds(x.net,1)} d</small></div><strong>${Math.round(x.__pct)}%</strong></div>${rblock(x.id)}</div>`).join('')}</div>`:`<div class="v1216b-top-empty"><b>Aún no hay Moves RigGO finalizadas disponibles para reaccionar.</b><span>El ranking Top puede incluir histórico Legacy; las reacciones solo se guardan contra una Move RigGO real con UUID.</span></div>`}`;host.insertAdjacentElement('afterend',panel);bindReactionButtons(panel)}
function injectPerformance(){if(state?.screen!=='overall')return;if(state.overallTab==='live')injectLive();else if(state.overallTab==='top')injectTop()}
async function post(){bindFlatAddButtons();decorateFlatEditors();syncOpsPreview();if(state?.screen==='overall'&&['live','top'].includes(state.overallTab)){const ids=reactionIds();await loadR(ids);injectPerformance()}}

